-- ============================================================
-- 测试数据验证脚本
-- 用于验证 TestDataGenerator 生成的数据是否符合预期
-- ============================================================

-- 1. 查看各表数据量统计
SELECT 'CATEGORY' AS TableName, COUNT(*) AS Count FROM CATEGORY
UNION ALL SELECT 'TAG', COUNT(*) FROM TAG
UNION ALL SELECT 'VENUE', COUNT(*) FROM VENUE
UNION ALL SELECT 'SEAT_MAP', COUNT(*) FROM SEAT_MAP
UNION ALL SELECT 'SEAT_SECTION', COUNT(*) FROM SEAT_SECTION
UNION ALL SELECT 'SEAT', COUNT(*) FROM SEAT
UNION ALL SELECT 'SHOW', COUNT(*) FROM SHOW
UNION ALL SELECT 'SHOW_TAG', COUNT(*) FROM SHOW_TAG
UNION ALL SELECT 'SHOW_SESSION', COUNT(*) FROM SHOW_SESSION
UNION ALL SELECT 'PRICE_STRATEGY', COUNT(*) FROM PRICE_STRATEGY
UNION ALL SELECT 'PURCHASE_LIMIT', COUNT(*) FROM PURCHASE_LIMIT
ORDER BY TableName;


-- 2. 验证演出数量是否为10场
SELECT 
    'SHOW_COUNT' AS CheckName,
    COUNT(*) AS Actual,
    10 AS Expected,
    CASE WHEN COUNT(*) = 10 THEN 'PASS' ELSE 'FAIL' END AS Status
FROM SHOW;


-- 3. 验证每场演出的场次数（3~5场）
SELECT 
    s.SHOW_NAME,
    COUNT(ss.SESSION_ID) AS SessionCount,
    CASE 
        WHEN COUNT(ss.SESSION_ID) BETWEEN 3 AND 5 THEN 'PASS'
        ELSE 'FAIL'
    END AS Status
FROM SHOW s
LEFT JOIN SHOW_SESSION ss ON s.SHOW_ID = ss.SHOW_ID
GROUP BY s.SHOW_ID, s.SHOW_NAME
ORDER BY s.SHOW_NAME;


-- 4. 验证每个场次的座位数（约200个）
SELECT 
    s.SHOW_NAME,
    ss.SESSION_ID,
    ss.START_TIME,
    ss.SESSION_STATUS,
    COUNT(st.SEAT_ID) AS SeatCount,
    CASE 
        WHEN COUNT(st.SEAT_ID) >= 180 AND COUNT(st.SEAT_ID) <= 220 THEN 'PASS'
        ELSE 'FAIL'
    END AS Status
FROM SHOW_SESSION ss
JOIN SHOW s ON ss.SHOW_ID = s.SHOW_ID
JOIN SEAT_MAP sm ON ss.SEAT_MAP_ID = sm.SEAT_MAP_ID
JOIN SEAT_SECTION sec ON sec.SEAT_MAP_ID = sm.SEAT_MAP_ID
JOIN SEAT st ON st.SEAT_SECTION_ID = sec.SEAT_SECTION_ID
GROUP BY s.SHOW_NAME, ss.SESSION_ID, ss.START_TIME, ss.SESSION_STATUS
ORDER BY ss.SESSION_ID
LIMIT 20;


-- 5. 验证场次状态分布
SELECT 
    SESSION_STATUS,
    COUNT(*) AS Count,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM SHOW_SESSION), 2) AS Percentage
FROM SHOW_SESSION
GROUP BY SESSION_STATUS
ORDER BY Count DESC;


-- 6. 验证演出状态分布
SELECT 
    STATUS,
    COUNT(*) AS Count,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM SHOW), 2) AS Percentage
FROM SHOW
GROUP BY STATUS
ORDER BY Count DESC;


-- 7. 验证审核状态分布
SELECT 
    AUDIT_STATUS,
    COUNT(*) AS Count,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM SHOW), 2) AS Percentage
FROM SHOW
GROUP BY AUDIT_STATUS
ORDER BY Count DESC;


-- 8. 验证票价策略分布
SELECT 
    PRICE_TYPE,
    COUNT(*) AS Count,
    MIN(PRICE) AS MinPrice,
    MAX(PRICE) AS MaxPrice,
    AVG(PRICE) AS AvgPrice
FROM PRICE_STRATEGY
GROUP BY PRICE_TYPE
ORDER BY PRICE_TYPE;


-- 9. 验证限购策略分布
SELECT 
    LIMIT_TYPE,
    CHANNEL,
    USER_TYPE,
    COUNT(*) AS Count,
    AVG(MAX_BUY_COUNT) AS AvgLimit
FROM PURCHASE_LIMIT
GROUP BY LIMIT_TYPE, CHANNEL, USER_TYPE
ORDER BY LIMIT_TYPE, CHANNEL, USER_TYPE;


-- 10. 验证场馆与座位图关系
SELECT 
    v.VENUE_NAME,
    COUNT(DISTINCT sm.SEAT_MAP_ID) AS SeatMapCount
FROM VENUE v
LEFT JOIN SEAT_MAP sm ON v.VENUE_ID = sm.VENUE_ID
GROUP BY v.VENUE_NAME
ORDER BY SeatMapCount DESC;

-- ============================================================
-- 扩展验证（当前 38 表 schema）
-- ============================================================

-- 11. 用户/权限扩展表数据量
SELECT 'ORG_STRUCTURE' AS TableName, COUNT(*) AS Count FROM ORG_STRUCTURE
UNION ALL SELECT 'USER_BLACKLIST', COUNT(*) FROM USER_BLACKLIST
UNION ALL SELECT 'USER_SESSION', COUNT(*) FROM USER_SESSION
UNION ALL SELECT 'OPERATION_LOG', COUNT(*) FROM OPERATION_LOG
UNION ALL SELECT 'USER_REAL_NAME', COUNT(*) FROM USER_REAL_NAME
UNION ALL SELECT 'ROLE', COUNT(*) FROM ROLE
UNION ALL SELECT 'PERMISSION', COUNT(*) FROM PERMISSION
ORDER BY TableName;


-- 12. 支撑/营销数据量
SELECT 'MARKETING_CONTENT' AS TableName, COUNT(*) AS Count FROM MARKETING_CONTENT
UNION ALL SELECT 'DYNAMIC_PRICING_RULE', COUNT(*) FROM DYNAMIC_PRICING_RULE
UNION ALL SELECT 'SEAT_RULE', COUNT(*) FROM SEAT_RULE
UNION ALL SELECT 'SEAT_RULE_SCOPE', COUNT(*) FROM SEAT_RULE_SCOPE
UNION ALL SELECT 'REFUND_POLICY', COUNT(*) FROM REFUND_POLICY
UNION ALL SELECT 'EXCHANGE_POLICY', COUNT(*) FROM EXCHANGE_POLICY
ORDER BY TableName;


-- 13. 订单/票务数据量
SELECT 'T_ORDER' AS TableName, COUNT(*) AS Count FROM T_ORDER
UNION ALL SELECT 'ORDER_ITEM', COUNT(*) FROM ORDER_ITEM
UNION ALL SELECT 'PAYMENT', COUNT(*) FROM PAYMENT
UNION ALL SELECT 'E_TICKET', COUNT(*) FROM E_TICKET
UNION ALL SELECT 'SEAT_LOCK', COUNT(*) FROM SEAT_LOCK
UNION ALL SELECT 'SEAT_RESERVATION', COUNT(*) FROM SEAT_RESERVATION
UNION ALL SELECT 'REFUND_REQUEST', COUNT(*) FROM REFUND_REQUEST
UNION ALL SELECT 'REFUND_ITEM', COUNT(*) FROM REFUND_ITEM
UNION ALL SELECT 'EXCHANGE_REQUEST', COUNT(*) FROM EXCHANGE_REQUEST
UNION ALL SELECT 'EXCHANGE_ITEM', COUNT(*) FROM EXCHANGE_ITEM
ORDER BY TableName;


-- 14. 订单状态分布
SELECT ORDER_STATUS, COUNT(*) AS Count
FROM T_ORDER
GROUP BY ORDER_STATUS
ORDER BY Count DESC;


-- 15. 订单金额一致性（订单 = 明细金额合计，支付金额一致）
SELECT
    COUNT(*) AS TotalOrders,
    SUM(CASE WHEN o.TOTAL_AMOUNT = item_total AND o.TICKET_COUNT = item_count THEN 1 ELSE 0 END) AS ConsistentOrders
FROM T_ORDER o
JOIN (
    SELECT ORDER_ID, SUM(UNIT_PRICE) AS item_total, COUNT(*) AS item_count
    FROM ORDER_ITEM GROUP BY ORDER_ID
) it ON it.ORDER_ID = o.ORDER_ID;


-- 16. 电子票状态分布
SELECT TICKET_STATUS, COUNT(*) AS Count
FROM E_TICKET
GROUP BY TICKET_STATUS
ORDER BY Count DESC;
